-- Financing settlement balances, not annual resources or verified payments.
CREATE TABLE public.territorial_financing_snapshot (
 scope text PRIMARY KEY CHECK(scope='settlement-2024'),
 metadata jsonb NOT NULL CHECK(metadata->>'version'='territorial-financing-2024-v1' AND (metadata->>'year')::integer=2024 AND jsonb_typeof(metadata->'records')='array' AND jsonb_array_length(metadata->'records')=17)
);
ALTER TABLE public.territorial_financing_snapshot ENABLE ROW LEVEL SECURITY;
